 const value=String(text||'').toUpperCase().replace(/[^0-9A-Z. $/+%\-]/g,'');if(!value)return '';
 const full='*'+value+'*',narrow=2,wide=5,gap=2,quiet=18,h=76;let x=quiet,bars=[];
 for(const ch of full){const p=CODE39[ch];if(!p)continue;for(let i=0;i<9;i++){const w=p[i]==='w'?wide:narrow;if(i%2===0)bars.push(`<rect x="${x}" y="0" width="${w}" height="${h}"/>`);x+=w;}x+=gap;}
