function pumpDesignation(a,u){return ('V-VA-'+String(a.name||'').trim()+' '+String(u.name||'').trim()).trim();}
function unitQrValue(a,u){const stored=String(u&&u.barcode||'').trim();return stored||pumpDesignation(a,u);}
function unitQrPayload(a,u){return unitQrValue(a,u);}
